// Shared RDS Data API helper. Every Lambda function requires() this instead
// of managing its own SQL client — keeps connection/credential handling in
// one place, and means functions don't need to be VPC-attached at all.
//
// CommonJS (not ESM) deliberately: AWS Lambda Layers mount at
// /opt/nodejs/node_modules, which Node's require() resolves correctly via
// NODE_PATH — but ESM's import does NOT check that same location for bare
// specifiers. Using require() here sidesteps that Lambda+Layers+ESM gotcha
// entirely, for this file and for every AWS SDK package each function pulls
// in directly.
const { RDSDataClient, ExecuteStatementCommand } = require("@aws-sdk/client-rds-data");

const client = new RDSDataClient({});

const RESOURCE_ARN = process.env.DB_CLUSTER_ARN;
const SECRET_ARN = process.env.DB_SECRET_ARN;
const DATABASE = process.env.DB_NAME;

function toField(value) {
  if (value === null || value === undefined) return { isNull: true };
  if (typeof value === "boolean") return { booleanValue: value };
  if (typeof value === "number") {
    return Number.isInteger(value) ? { longValue: value } : { doubleValue: value };
  }
  if (typeof value === "object") return { stringValue: JSON.stringify(value) };
  return { stringValue: String(value) };
}

function fromField(field) {
  if (field.isNull) return null;
  if ("stringValue" in field) return field.stringValue;
  if ("longValue" in field) return field.longValue;
  if ("doubleValue" in field) return field.doubleValue;
  if ("booleanValue" in field) return field.booleanValue;
  if ("blobValue" in field) return field.blobValue;
  return null;
}

async function query(sql, params = {}) {
  const parameters = Object.entries(params).map(([name, value]) => ({
    name,
    value: toField(value),
  }));

  const command = new ExecuteStatementCommand({
    resourceArn: RESOURCE_ARN,
    secretArn: SECRET_ARN,
    database: DATABASE,
    sql,
    parameters,
    includeResultMetadata: true,
  });

  // Aurora Serverless v2 auto-pauses when idle (to avoid charging for
  // compute nobody's using) and takes roughly 15s to wake back up on the
  // first request after a pause. The Data API doesn't wait for that itself
  // — it returns DatabaseResumingException and expects the caller to retry.
  // Budget kept deliberately under API Gateway's hard 30-second integration
  // timeout (a fixed ceiling for HTTP APIs, not configurable) — 4 attempts
  // at a 5s delay is 20s of waiting, leaving real margin for the actual
  // request time and network overhead before the gateway itself would cut
  // the connection with a generic timeout.
  const maxAttempts = 4;
  const delayMs = 5000;
  let lastError;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const result = await client.send(command);

      if (!result.records) return { rows: [], numberOfRecordsUpdated: result.numberOfRecordsUpdated ?? 0 };

      // For Postgres, the RDS Data API sets `name` to the ORIGINAL source
      // column and `label` to the SQL alias. Mapping on `name` means two
      // aliased columns drawn from the same underlying column (e.g.
      // `c.user_id AS comment_author_id` and `d.user_id AS diagram_owner_id`)
      // both land on the key `user_id`, and the second silently clobbers the
      // first. Preferring `label` keeps aliases intact; it falls back to
      // `name` for unaliased columns, where the two are identical anyway.
      const columns = (result.columnMetadata || []).map((c) => c.label || c.name);

      // Temporary probe — set DB_DEBUG_COLUMNS=1 on a function to dump the
      // raw metadata to CloudWatch once, confirm the name/label behaviour,
      // then unset it and delete this block.
      if (process.env.DB_DEBUG_COLUMNS === "1") {
        console.log("COLUMN_METADATA_PROBE", JSON.stringify(
          (result.columnMetadata || []).map((c) => ({ name: c.name, label: c.label }))
        ));
      }
      const rows = result.records.map((record) => {
        const row = {};
        record.forEach((field, i) => {
          row[columns[i]] = fromField(field);
        });
        return row;
      });

      return { rows, numberOfRecordsUpdated: result.numberOfRecordsUpdated ?? 0 };
    } catch (err) {
      lastError = err;
      const isResuming = err.name === "DatabaseResumingException" || err.__type?.includes("DatabaseResumingException");
      if (!isResuming || attempt === maxAttempts) throw err;
      console.log(`Aurora is resuming from auto-pause, attempt ${attempt}/${maxAttempts} — waiting ${delayMs}ms before retry`);
      await new Promise((resolve) => setTimeout(resolve, delayMs));
    }
  }

  throw lastError;
}

function newId(prefix) {
  return `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
}

// Idempotent — safe to call unconditionally whether or not this user's row
// already exists (uses INSERT IGNORE), so both signup and sign-in can call
// this on every success without worrying about duplicate-key errors. This
// is what makes sign-in self-healing: if an earlier bug ever let someone's
// Cognito account get created without a corresponding local row (exactly
// what happened during this project's own debugging), the next successful
// sign-in quietly repairs it rather than leaving a permanently broken
// account that can authenticate but can't do anything requiring that row.
async function ensureUserRow(userId, email, displayName, handle) {
  await query(
    `INSERT IGNORE INTO users (user_id, email, auth_provider, display_name, avatar_initials, handle)
     VALUES (:userId, :email, 'email', :displayName, :initials, :handle)`,
    {
      userId,
      email,
      displayName: displayName || email.split("@")[0],
      initials: (displayName || email).slice(0, 2).toUpperCase(),
      // A chosen handle when the user picked one at signup; otherwise a
      // placeholder they can change later from their profile.
      handle: handle || newId("user").slice(0, 20),
    }
  );
}

// Handle rules, shared so signup and profile-edit can't disagree about them.
const HANDLE_RE = /^[a-z0-9_]{3,20}$/;
function validateHandle(raw) {
  const h = String(raw || "").trim().toLowerCase().replace(/^@/, "");
  if (!h) return { ok: false, reason: "Please choose a handle." };
  if (h.length < 3) return { ok: false, reason: "Handles must be at least 3 characters." };
  if (h.length > 20) return { ok: false, reason: "Handles can be at most 20 characters." };
  if (!HANDLE_RE.test(h)) return { ok: false, reason: "Handles can only use lowercase letters, numbers and underscores." };
  // Reserved words that would collide with routes or impersonate the platform.
  const RESERVED = ["admin","administrator","support","help","root","system","official",
                    "cloudforger","staff","moderator","mod","api","settings","me","null","undefined"];
  if (RESERVED.includes(h)) return { ok: false, reason: "That handle is reserved." };
  return { ok: true, handle: h };
}

async function isHandleTaken(handle) {
  const { rows } = await query(`SELECT user_id FROM users WHERE handle = :handle`, { handle });
  return rows.length > 0;
}

module.exports = { query, newId, ensureUserRow, validateHandle, isHandleTaken };
